// ---- generated by scripts/make_tests.py of the probe: the readers
[[nodiscard]] std::string readAxialStageCDOverridden(const RocketComponent& c)
{
    return flag(as<AxialStage>(c).isCDOverridden());
}

[[nodiscard]] std::string readAxialStageOverrideCDAndCDOverridden(const RocketComponent& c)
{
    return list(num(as<AxialStage>(c).getOverrideCD()), flag(as<AxialStage>(c).isCDOverridden()));
}

